<header class="sticky top-0 z-20 flex min-h-20 shrink-0 items-center justify-between gap-3 border-b border-slate-200 bg-white/95 px-4 py-3 backdrop-blur sm:px-8">
    <div class="flex items-center gap-3"><button type="button" @click="sidebarOpen=!sidebarOpen" aria-label="Buka atau tutup menu" class="h-11 w-11 rounded-xl border border-slate-200 text-slate-600">☰</button><div><p class="text-sm font-bold text-slate-900">Atur Shift</p><p class="hidden text-xs text-slate-500 sm:block">Tim kecil. Jadwal jelas.</p></div></div>
    <div class="flex items-center gap-2"><span class="hidden text-xs text-slate-500 md:block" x-text="dirty?'Ada rancangan belum disimpan':'WITA · UTC+8'"></span><button type="button" @click="save()" :disabled="saving||loading||!activeDirty||conflicts.length>0" class="min-h-[44px] rounded-xl bg-brand-700 px-4 text-sm font-bold text-white disabled:opacity-40" x-text="saving?'Menyimpan…':(daily?'Simpan tanggal':'Simpan pola periode')"></button></div>
</header>
<div class="mx-auto w-full max-w-[1600px] space-y-5 p-4 pb-24 sm:p-7">
    <section class="flex items-center justify-between gap-6 rounded-3xl border border-emerald-100 bg-white p-5 sm:p-7">
        <div><p class="text-xs font-bold uppercase tracking-widest text-brand-700">Ruang kerja tim</p><h1 class="mt-2 text-2xl font-extrabold tracking-tight text-slate-900 sm:text-3xl">Susun shift, semudah pindah kartu.</h1><p class="mt-3 max-w-2xl text-sm leading-6 text-slate-500">Tarik nama ke shift, atau pilih lewat formulir. Maksimal 3 orang per shift, dengan jam kerja yang bisa kamu atur sendiri.</p></div>
        <svg viewBox="0 0 180 110" class="hidden h-28 w-44 shrink-0 sm:block" fill="none" aria-hidden="true"><rect x="8" y="12" width="164" height="88" rx="18" fill="#ECFDF5"/><path d="M42 34H137M42 81H137" stroke="#A7F3D0" stroke-width="3" stroke-linecap="round"/><rect x="28" y="40" width="36" height="32" rx="10" fill="#D1FAE5"/><rect x="72" y="40" width="36" height="32" rx="10" fill="#A7F3D0"/><rect x="116" y="40" width="36" height="32" rx="10" fill="#6EE7B7"/><circle cx="46" cy="51" r="5" fill="#047857"/><circle cx="90" cy="51" r="5" fill="#047857"/><circle cx="134" cy="51" r="5" fill="#047857"/><path d="M38 65C38 56 54 56 54 65M82 65C82 56 98 56 98 65M126 65C126 56 142 56 142 65" stroke="#047857" stroke-width="3" stroke-linecap="round"/></svg>
    </section>
    <p x-show="loading" role="status" class="rounded-xl bg-white p-4 text-sm text-slate-500">Memuat jadwal dan akun tim…</p>
    <div aria-live="polite"><p x-show="saved" x-text="saved" class="rounded-xl border border-emerald-200 bg-emerald-50 p-4 text-sm text-emerald-800"></p></div>
    <div x-show="error" role="alert" class="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-800"><span x-text="error"></span><button type="button" @click="reload()" :disabled="saving||loading" class="min-h-[44px] rounded-lg border border-red-200 px-3 font-semibold">Muat ulang</button></div>
    <template x-if="config&&period">
        <div class="space-y-5" :aria-busy="saving||loading">
            <section class="flex flex-wrap items-center justify-between gap-4 rounded-2xl border border-slate-200 bg-white p-4 sm:p-5">
                <div><p class="text-xs font-semibold text-slate-500">Periode kerja · tanggal 22–21</p><p class="mt-1 text-sm font-bold text-slate-900 sm:text-base" x-text="period.name"></p><p x-show="inherited" class="mt-1 text-xs text-amber-700">Pola awal dari pengaturan lama. Simpan untuk menetapkan periode ini.</p></div>
                <div class="flex gap-2"><button type="button" @click="movePeriod(-1)" :disabled="loading||saving" aria-label="Periode sebelumnya" class="h-11 w-11 rounded-xl border border-slate-200">←</button><button type="button" @click="movePeriod(1)" :disabled="loading||saving" aria-label="Periode berikutnya" class="h-11 w-11 rounded-xl border border-slate-200">→</button></div>
            </section>
            <nav aria-label="Tampilan shift" class="flex flex-wrap gap-2">
                <button type="button" @click="view='board'" :aria-pressed="view==='board'" :class="view==='board'?'bg-slate-900 text-white':'bg-white text-slate-600'" class="min-h-[44px] rounded-xl border border-slate-200 px-4 text-sm font-semibold">Papan shift</button>
                <button type="button" @click="view='summary'" :aria-pressed="view==='summary'" :class="view==='summary'?'bg-slate-900 text-white':'bg-white text-slate-600'" class="min-h-[44px] rounded-xl border border-slate-200 px-4 text-sm font-semibold">Analitik & ringkasan</button>
            </nav>
            <div x-show="view==='board'" class="space-y-5">
                <section class="rounded-2xl border border-slate-200 bg-white p-4 sm:p-5">
                    <div class="flex flex-wrap items-center justify-between gap-3"><div class="flex flex-wrap gap-2"><button type="button" @click="switchMode('period')" :aria-pressed="!daily" :class="!daily?'border-brand-600 bg-brand-50 text-brand-800':'border-slate-200 text-slate-600'" class="min-h-[44px] rounded-xl border px-4 text-sm font-semibold">1. Pola periode</button><button type="button" @click="switchMode('day')" :aria-pressed="daily" :class="daily?'border-brand-600 bg-brand-50 text-brand-800':'border-slate-200 text-slate-600'" class="min-h-[44px] rounded-xl border px-4 text-sm font-semibold">2. Revisi harian</button></div><button x-show="daily" type="button" @click="resetDate()" :disabled="saving||loading" class="min-h-[44px] px-3 text-xs font-semibold text-slate-600 underline">Kembali ke pola periode</button></div>
                    <p class="mt-3 text-sm leading-6 text-slate-500" x-text="daily?'Khusus '+dateLabel(selectedDate)+'. Perubahan tanggal ini tidak mengubah pola atau hari lainnya.':'Pola ini otomatis berlaku sepanjang periode, kecuali hari libur dan tanggal dengan revisi khusus.'"></p>
                    <p x-show="daily&&dayRevision" class="mt-2 text-xs font-bold text-indigo-700">Tanggal ini memiliki revisi khusus.</p>
                </section>
                @include('shifts.calendar')
                <section x-show="conflicts.length" role="alert" class="rounded-2xl border border-amber-200 bg-amber-50 p-5"><p class="text-sm font-bold text-amber-900">Perlu dirapikan sebelum disimpan</p><ul class="mt-2 list-inside list-disc text-sm leading-6 text-amber-900"><template x-for="message in conflicts" :key="message"><li x-text="message"></li></template></ul></section>
                <fieldset :disabled="saving||loading" class="min-w-0 space-y-5 disabled:opacity-60">
                    <legend class="sr-only">Pengaturan shift aktif</legend>
                    <section class="rounded-2xl border border-slate-200 bg-white p-5">
                        <div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
                            <label class="text-xs font-semibold text-slate-600">Mulai kerja · WITA<input type="time" x-model="activeConfig.start_time" class="mt-2 h-11 w-full rounded-xl border border-slate-200 px-3 text-sm"></label>
                            <label class="text-xs font-semibold text-slate-600">Jeda antarshift (menit)<input type="number" min="0" max="1440" x-model.number="activeConfig.charging_duration_min" class="mt-2 h-11 w-full rounded-xl border border-slate-200 px-3 text-sm"></label>
                            <label class="text-xs font-semibold text-slate-600">HP per orang / alat<input type="number" min="1" max="100" x-model.number="activeConfig.hp_per_tool" class="mt-2 h-11 w-full rounded-xl border border-slate-200 px-3 text-sm"></label>
                            <label x-show="!daily" class="text-xs font-semibold text-slate-600">Hari libur rutin<select x-model="config.day_off" class="mt-2 h-11 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm"><option value="none">Tanpa libur tetap</option><option value="monday">Senin</option><option value="tuesday">Selasa</option><option value="wednesday">Rabu</option><option value="thursday">Kamis</option><option value="friday">Jumat</option><option value="saturday">Sabtu</option><option value="sunday">Minggu</option></select></label>
                        </div>
                        <div class="mt-4 flex flex-wrap items-center justify-between gap-3 border-t border-slate-100 pt-4"><p class="text-xs text-slate-500"><strong class="text-slate-800" x-text="filledSlots+' / '+(shifts.length*3)"></strong> slot terisi · <strong class="text-slate-800" x-text="number(dayHours)+' jam kerja tim'"></strong> per hari</p><div class="flex gap-2"><button type="button" @click="removeShift()" :disabled="shifts.length<=1" class="min-h-[44px] rounded-xl border border-slate-200 px-3 text-xs disabled:opacity-30">Hapus shift terakhir</button><button type="button" @click="addShift()" :disabled="shifts.length>=12" class="min-h-[44px] rounded-xl border border-brand-200 bg-brand-50 px-3 text-xs font-semibold text-brand-800 disabled:opacity-30">+ Shift</button></div></div>
                    </section>
                    <section class="rounded-2xl border border-slate-200 bg-white p-5">
                        <p class="text-sm font-bold text-slate-900">Tambah lewat pilihan</p><p class="mt-1 text-xs text-slate-500">Cara yang sama praktisnya di ponsel atau dengan keyboard. Satu orang boleh mengambil beberapa shift.</p>
                        <div class="mt-4 grid gap-3 sm:grid-cols-[minmax(0,1fr)_160px_auto]"><label class="text-xs font-semibold text-slate-600">Anggota<select x-model="chosenPerson" class="mt-2 h-11 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm"><option value="">Pilih anggota</option><template x-for="c in contributors" :key="c.id"><option :value="c.id" x-text="c.nama"></option></template></select></label><label class="text-xs font-semibold text-slate-600">Tujuan<select x-model.number="chosenShift" class="mt-2 h-11 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm"><template x-for="s in shifts" :key="s.id"><option :value="s.id" x-text="'Shift '+s.id+' ('+shiftMembers(s.id).length+'/3)'"></option></template></select></label><button type="button" @click="assign(chosenPerson,chosenShift)" :disabled="!chosenPerson" class="min-h-[44px] self-end rounded-xl bg-brand-700 px-5 text-sm font-semibold text-white disabled:opacity-30">Tempatkan</button></div>
                    </section>
                    <div class="grid items-start gap-5 xl:grid-cols-[270px_minmax(0,1fr)]">
                        <aside class="overflow-hidden rounded-2xl border border-slate-200 bg-white" @dragover.prevent="dropTarget=0" @drop="drop($event,0)">
                            <div class="border-b border-slate-100 p-4"><h2 class="text-sm font-bold text-slate-900">Anggota tim</h2><p class="mt-1 text-xs leading-5 text-slate-500">Tarik ke kartu shift. Tarik kembali ke sini untuk melepas satu penugasan.</p><label class="mt-3 block"><span class="sr-only">Cari anggota</span><input type="search" x-model="search" placeholder="Cari nama…" class="h-11 w-full rounded-xl border border-slate-200 bg-slate-50 px-3 text-sm"></label></div>
                            <div class="max-h-[620px] space-y-2 overflow-y-auto p-3"><template x-for="row in roster" :key="row.id"><article draggable="true" @dragstart="startDrag($event,row.id)" @dragend="drag=null;dropTarget=null" class="cursor-grab rounded-xl border border-slate-100 bg-slate-50 p-3 active:cursor-grabbing" :class="row.person?.status&&row.person.status!=='scheduled'?'border-amber-200 bg-amber-50':''">
                                <div class="flex items-center gap-3"><span class="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-white text-xs font-bold text-brand-700" x-text="initials(row.name)"></span><div class="min-w-0"><h3 class="break-words text-sm font-semibold text-slate-800" x-text="row.name"></h3><p class="mt-0.5 text-xs text-slate-500" x-text="row.person?.sessions.length?'Shift '+row.person.sessions.join(', '):'Belum ada shift'"></p></div></div>
                                <p class="mt-2 text-xs" :class="row.linked?'text-brand-700':'text-slate-500'" x-text="row.linked?'Akun worker aktif':'Akun belum aktif'"></p>
                                <div x-show="daily" class="mt-3 space-y-2"><label class="block text-xs text-slate-600">Status tanggal ini<select :value="row.person?.status||'scheduled'" @change="setStatus(row.id,$event.target.value);$event.target.value=activeConfig.karyawan.find(p=>String(personKey(p))===String(row.id))?.status||'scheduled'" class="mt-1 h-11 w-full rounded-lg border border-slate-200 bg-white px-2 text-sm"><template x-for="(label,key) in statuses" :key="key"><option :value="key" x-text="label"></option></template></select></label><template x-if="row.person"><label class="block text-xs text-slate-600">Catatan untuk worker<input type="text" maxlength="300" x-model="row.person.note" placeholder="Opsional" class="mt-1 h-11 w-full rounded-lg border border-slate-200 bg-white px-2 text-sm"></label></template></div>
                                <button x-show="row.person?.sessions.length" type="button" @click="clearAssignments(row.id)" class="mt-2 min-h-[44px] text-xs font-semibold text-slate-500 underline">Lepas semua shift</button>
                            </article></template><p x-show="!roster.length" class="p-3 text-sm text-slate-500">Anggota tidak ditemukan.</p></div>
                        </aside>
                        <div class="grid min-w-0 gap-4 md:grid-cols-2 2xl:grid-cols-3"><template x-for="shift in shifts" :key="shift.id"><section @dragover.prevent="dropTarget=shift.id" @dragleave.self="dropTarget=null" @drop="drop($event,shift.id)" :class="dropTarget===shift.id?'ring-2 ring-brand-500 border-brand-300':'border-slate-200'" class="min-w-0 overflow-hidden rounded-2xl border bg-white">
                            <div class="border-b border-slate-100 p-5"><div class="flex items-center justify-between gap-2"><h2 class="text-base font-bold text-slate-900" x-text="'Shift '+shift.id"></h2><span class="rounded-full px-2.5 py-1 text-xs font-bold" :class="shiftMembers(shift.id).length===3?'bg-amber-50 text-amber-800':'bg-brand-50 text-brand-700'" x-text="shiftMembers(shift.id).length+' / 3 orang'"></span></div><p class="mt-2 text-sm font-semibold tabular-nums text-brand-700" x-text="shift.start+' – '+shift.end"></p><label class="mt-4 flex items-center justify-between gap-3 text-xs text-slate-500">Durasi (menit)<input type="number" min="1" max="1440" x-model.number="activeConfig.session_durations[shift.id-1]" class="h-11 w-24 rounded-lg border border-slate-200 px-3 text-sm font-semibold text-slate-800"></label></div>
                            <div class="min-h-[210px] space-y-3 p-4"><template x-for="(person,index) in shiftMembers(shift.id)" :key="personKey(person)"><article draggable="true" @dragstart.stop="startDrag($event,personKey(person),shift.id)" @dragend="drag=null;dropTarget=null" class="cursor-grab rounded-xl border border-emerald-100 bg-emerald-50/70 p-3 active:cursor-grabbing">
                                <div class="flex items-start justify-between gap-2"><div class="flex min-w-0 items-center gap-2"><span class="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-white text-xs font-bold text-brand-700" x-text="initials(person.name)"></span><p class="break-words text-sm font-semibold text-slate-800" x-text="person.name"></p></div><button type="button" @click="assign(personKey(person),0,shift.id)" :aria-label="'Lepas '+person.name+' dari Shift '+shift.id" class="h-11 w-11 shrink-0 rounded-lg text-slate-500">×</button></div>
                                <p class="mt-1 text-xs text-emerald-800" x-text="'Alat '+(index+1)+' · '+number(shift.duration/60)+' jam kerja'"></p><label class="mt-3 block text-xs text-slate-600">Pindahkan ke<select @change="assign(personKey(person),$event.target.value,shift.id);$event.target.value=''" class="mt-1 h-11 w-full rounded-lg border border-emerald-200 bg-white px-2 text-sm"><option value="">Pilih shift lain…</option><template x-for="other in shifts.filter(s=>s.id!==shift.id)" :key="other.id"><option :value="other.id" x-text="'Shift '+other.id+' ('+shiftMembers(other.id).length+'/3)'"></option></template></select></label>
                            </article></template><div x-show="shiftMembers(shift.id).length<3" class="flex min-h-[80px] items-center justify-center rounded-xl border-2 border-dashed border-slate-200 p-4 text-center text-xs leading-5 text-slate-400">Tarik anggota ke sini<br>atau gunakan pilihan di atas</div></div>
                        </section></template></div>
                    </div>
                    <section x-show="unlinked.length" class="rounded-2xl border border-amber-200 bg-amber-50 p-5"><h2 class="text-sm font-bold text-amber-900">Hubungkan nama dari jadwal lama</h2><p class="mt-2 text-sm text-amber-800">Pilih kontributor yang benar agar jadwal masuk ke akunnya. Jadwal lama tetap tersedia sampai perubahan disimpan.</p><div class="mt-3 space-y-3"><template x-for="p in unlinked" :key="p.name"><div class="flex flex-wrap items-center gap-3"><span class="text-sm font-semibold" x-text="p.name"></span><select @change="linkPerson(personKey(p),$event.target.value)" :aria-label="'Hubungkan '+p.name" class="h-11 max-w-full rounded-lg border border-amber-200 bg-white px-3 text-sm"><option value="">Pilih kontributor…</option><template x-for="c in contributors" :key="c.id"><option :value="c.id" x-text="c.nama"></option></template></select><button type="button" @click="removePerson(personKey(p))" class="min-h-[44px] px-2 text-xs font-semibold underline">Keluarkan dari pola</button></div></template></div></section>
                </fieldset>
                <div class="flex flex-wrap items-center justify-between gap-3 rounded-2xl bg-slate-900 p-5 text-white"><p class="max-w-xl text-sm leading-6" x-text="daily?'Izin dan sakit hanya mengubah rencana kerja tanggal ini. Catatan dapat dilihat oleh worker.':'Alat 1–3 dibagikan otomatis per shift. Revisi harian yang sudah tersimpan tetap dipertahankan.'"></p><button type="button" @click="discard()" :disabled="saving||loading||!(daily?dayDirty:periodDirty)" class="min-h-[44px] rounded-xl border border-slate-600 px-4 text-sm font-semibold disabled:opacity-30">Batalkan rancangan</button></div>
            </div>
            <section x-show="view==='summary'" class="space-y-5">
                <p x-show="dirty||inherited" class="rounded-xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-900">Ringkasan mencakup rancangan yang belum disimpan. Simpan pola dan revisi harian untuk menerapkannya ke akun worker.</p>
                <div class="grid grid-cols-2 gap-3 lg:grid-cols-4"><template x-for="stat in [{label:'Hari aktif',value:summary.activeDays+' hari'},{label:'Jam kerja tim',value:number(summary.hours)+' jam'},{label:'Kapasitas video',value:number(summary.production)+' jam'},{label:'Izin / sakit',value:summary.absences+' orang-hari'}]" :key="stat.label"><div class="rounded-2xl border border-slate-200 bg-white p-5"><p class="text-xs text-slate-500" x-text="stat.label"></p><p class="mt-3 text-xl font-bold text-slate-900" x-text="stat.value"></p></div></template></div>
                <div class="grid gap-5 lg:grid-cols-2"><section class="rounded-2xl border border-slate-200 bg-white p-5"><h2 class="text-base font-bold text-slate-900">Sebaran beban kerja</h2><p class="mt-2 text-xs leading-5 text-slate-500">Jam efektif sesuai rencana, setelah hari libur dan izin/sakit. Kehadiran aktual tetap dicatat lewat absensi.</p><div class="mt-5 space-y-4"><template x-for="p in summary.rows" :key="p.id"><div><div class="flex justify-between gap-3 text-sm"><span class="truncate font-semibold text-slate-700" x-text="p.name"></span><span class="shrink-0 tabular-nums text-slate-500" x-text="number(p.hours)+' jam'"></span></div><div class="mt-2 h-2 overflow-hidden rounded-full bg-slate-100"><div class="h-full rounded-full bg-brand-600" :style="'width:'+Math.max(0,Math.min(100,p.hours/Math.max(1,...summary.rows.map(r=>r.hours))*100))+'%'"></div></div><p class="mt-1 text-xs text-slate-500" x-text="p.days+' hari · izin '+p.izin+' · sakit '+p.sakit"></p></div></template><p x-show="!summary.rows.length" class="text-sm text-slate-500">Belum ada anggota pada periode ini.</p></div></section>
                    <section class="rounded-2xl border border-slate-200 bg-white p-5"><h2 class="text-base font-bold text-slate-900">Simulasi produksi & biaya</h2><div class="mt-5 grid gap-4 sm:grid-cols-2"><label class="text-xs font-semibold text-slate-600">Tarif per jam video (Rp)<input type="number" min="0" :disabled="saving||loading||daily" x-model.number="config.hourly_rate" class="mt-2 h-11 w-full rounded-xl border border-slate-200 px-3 text-sm"></label><label class="text-xs font-semibold text-slate-600">Estimasi lolos QA (%)<input type="number" min="0" max="100" :disabled="saving||loading||daily" x-model.number="config.qa_yield_rate" class="mt-2 h-11 w-full rounded-xl border border-slate-200 px-3 text-sm"></label></div><div class="mt-5 space-y-4 rounded-xl bg-slate-50 p-4"><div><p class="text-xs text-slate-500">Estimasi video lolos QA</p><p class="mt-1 text-xl font-bold text-brand-700" x-text="number(summary.production*config.qa_yield_rate/100)+' jam'"></p></div><div><p class="text-xs text-slate-500">Biaya kapasitas penuh · sebelum QA</p><p class="mt-1 text-xl font-bold text-slate-900" x-text="money(summary.cost)"></p></div><p class="text-xs leading-5 text-slate-500">Simulasi, bukan gaji aktual. Pembayaran tetap mengikuti hasil yang disetujui. Tarif ini disimpan bersama pola periode.</p></div><button type="button" @click="switchMode('period');view='board'" class="mt-4 min-h-[44px] text-sm font-semibold text-brand-700 underline">Kembali untuk menyimpan pola</button></section></div>
                <section class="rounded-2xl border border-slate-200 bg-white p-5"><div class="flex flex-wrap items-center justify-between gap-3"><h2 class="text-base font-bold text-slate-900">Ringkasan siap salin</h2><button type="button" @click="copySummary()" class="min-h-[44px] rounded-xl border border-brand-200 bg-brand-50 px-4 text-sm font-semibold text-brand-800">Salin ringkasan</button></div><label class="mt-4 block"><span class="sr-only">Ringkasan jadwal periode</span><textarea readonly :value="narrative" rows="12" class="w-full rounded-xl border border-slate-200 bg-slate-50 p-4 text-sm leading-7 text-slate-700"></textarea></label></section>
            </section>
        </div>
    </template>
</div>
